const ROW = cn('relative flex h-8 cursor-pointer items-center rounded-md text-start text-sm pointer-coarse:h-10', focusRingClass);

/**
 * Full-width row with a label, or a centred square matching the rail's icon
 * buttons. A rail badge stretches the square into a capsule: the glyph, then
 * the word, filling the rail's width so the word never overhangs the fill.
 */
const rowShape = (collapsed: boolean, badge = false) =>
	collapsed
		? badge
			? 'h-auto w-full shrink-0 flex-col justify-center gap-0.5 py-1.5'
			: 'size-8 shrink-0 justify-center pointer-coarse:size-10'
		: 'w-full gap-2 px-2';

/**
 * Labels a rail control with a tooltip while the sidebar is collapsed. A `tip`
 * adds a line under the label there, and is the whole tooltip when expanded.
 */
function RailTip({ label, collapsed, tip, children }: { label: string; collapsed: boolean; tip?: React.ReactNode; children: React.ReactElement }) {
	if (!collapsed && !tip) return children;
	return (
		<Tooltip>
			<TooltipTrigger render={children} />
			<TooltipContent side="right">
				{collapsed ? (
					<>
						{label}
						{tip ? <span className="block text-pretty text-muted-foreground">{tip}</span> : null}
					</>
				) : (
					tip
				)}
			</TooltipContent>
		</Tooltip>
	);
}

type NavRowProps = {
	label: string;
	collapsed: boolean;
	active?: boolean;
	/** Leading glyph: an icon, or any node such as a monogram. */
	leading: React.ReactNode;
	/** Replaces the plain label, e.g. with shimmering text. */
	labelNode?: React.ReactNode;
	/** Quiet trailing value such as a count. */
	trailing?: React.ReactNode;
	/** Tooltip detail, e.g. what an agent waits on. Shown expanded too; replaces the truncation title. */
	tip?: React.ReactNode;
	/** A short word under the collapsed square's glyph, e.g. "Approve". The square stretches into a capsule to hold it. */
	railBadge?: React.ReactNode;
	/** Row tone when not active. */
	muted?: boolean;
	/** Not choosable right now, e.g. while another row loads or policy forbids it. */
	disabled?: boolean;
	/** Loading this row's destination; announced and shown in place of the trailing value. */
	busy?: boolean;
	onClick?: () => void;
	/** Renders the row as a link to this address instead of a button. */
	href?: string;
	/** Renders the link through the host's router component. Default: a plain anchor. */
	renderLink?: (props: NavRowLinkProps) => React.ReactElement;
};

/** Props a link-mode row hands to `renderLink`. */
type NavRowLinkProps = Omit<React.ComponentProps<'a'>, 'href'> & { href: string };

/**
 * One sidebar row. Focus reads through weight and a tinted fill, never a
 * coloured dot; hover is instant because rows are clicked constantly.
 */
function NavRow({ label, collapsed, active, leading, labelNode, trailing, tip, railBadge, muted, disabled, busy, onClick, href, renderLink }: NavRowProps) {
	const badge = collapsed ? railBadge : null;
	const content = (
		<>
			{leading}
			{badge}
			{collapsed ? null : (
				<>
					<span title={tip ? undefined : label} className="min-w-0 flex-1 truncate">
						<bdi>{labelNode ?? label}</bdi>
					</span>
					{busy ? <Loader2 aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground motion-safe:animate-spin" /> : trailing}
				</>
			)}
		</>
	);
	const tone = active
		? 'bg-sidebar-accent font-medium text-foreground'
		: muted
			? 'text-muted-foreground'
			: 'text-sidebar-foreground';
	const shared = {
		'aria-label': collapsed ? label : undefined,
		'aria-current': active ? ('page' as const) : undefined,
		'aria-busy': busy || undefined,
	};
	let row: React.ReactElement;
	if (href !== undefined) {
		// A disabled link stays focusable and announced, but does nothing.
		const props: NavRowLinkProps = {
			...shared,
			href,
			'aria-disabled': disabled || undefined,
			onClick: (event) => {
				if (disabled) event.preventDefault();
				else onClick?.();
			},
			className: cn(
				ROW,
				rowShape(collapsed, Boolean(badge)),
				'no-underline',
				disabled ? 'cursor-not-allowed opacity-50' : cn('hover:bg-overlay-hover', muted && !active && 'hover:text-foreground'),
				tone,
			),
			children: content,
		};
		row = renderLink ? renderLink(props) : <a {...props} />;
	} else {
		row = (
			<button
				type="button"
				{...shared}
				disabled={disabled}
				onClick={onClick}
				className={cn(
					ROW,
					rowShape(collapsed, Boolean(badge)),
					'disabled:cursor-not-allowed disabled:opacity-50',
					active ? tone : cn('enabled:hover:bg-overlay-hover', tone, muted && 'enabled:hover:text-foreground'),
				)}
			>
				{content}
			</button>
		);
	}
	return (
		<li className={collapsed ? 'flex justify-center' : undefined}>
			<RailTip label={label} collapsed={collapsed} tip={tip}>
				{row}
			</RailTip>
		</li>
	);
}

function NavIcon({ icon: Icon, active }: { icon: LucideIcon; active?: boolean }) {
	return <Icon aria-hidden="true" className={cn('size-3.5 shrink-0', active ? 'text-foreground' : 'text-muted-foreground')} />;
}

/**
 * Quiet trailing count for a nav row; hidden from assistive tech, which reads
 * the label instead. A number is grouped (`1,284`); pass a string to format it yourself.
 */
function NavCount({ value, tone = 'muted', locale }: { value: React.ReactNode; tone?: 'muted' | 'warning' | 'danger'; locale?: string }) {
	return (
		<span
			aria-hidden="true"
			className={cn(
				'text-xs tabular-nums',
				tone === 'muted' && 'text-muted-foreground',
				tone === 'warning' && 'font-medium text-warning',
				tone === 'danger' && 'font-medium text-destructive',
			)}
		>
			{typeof value === 'number' ? formatCount(value, locale) : value}
		</span>
	);
}

type NavSectionProps = {
	/** Visible heading above the rows; hidden in the icon rail. */
	title?: string;
	collapsed: boolean;
	/** Optional control beside the heading, such as an add button. */
	action?: React.ReactNode;
	children: React.ReactNode;
};

/** A group of rows with an optional small heading. */
function NavSection({ title, collapsed, action, children }: NavSectionProps) {
	const headingId = React.useId();
	return (
		<div className="flex w-full flex-col gap-1">
			{/* In the icon rail a heading has nothing to show, so only an action keeps the row. */}
			{(title && !collapsed) || action ? (
				<div className={cn('flex h-7 items-center gap-2 ps-2', collapsed && 'justify-center ps-0')}>
					{collapsed || !title ? null : (
						<h2 id={headingId} className="flex-1 truncate text-xs text-muted-foreground">
							{title}
						</h2>
					)}
					{action}
				</div>
			) : null}
			<ul
				aria-labelledby={title && !collapsed ? headingId : undefined}
				aria-label={title && collapsed ? title : undefined}
				className="flex flex-col gap-0.5"
			>
				{children}
			</ul>
		</div>
	);
}

type SidebarFrameProps = {
	/** Accessible name of the navigation landmark. */
	label: string;
	/** Workspace or account switcher at the top left. */
	menu: React.ReactNode;
	collapsed: boolean;
	onCollapsedChange?: (collapsed: boolean) => void;
