	/** Set false when neighbours sit closer than the extended hit area. */
	extendHitArea?: boolean;
	/** For a menu trigger: it keeps its hover fill while the menu is open, so the menu reads as coming from it. */
	menu?: boolean;
};

/**
 * The look of `TooltipIconButton`, for icon-only controls that render their own
 * element, such as a menu trigger. Hover state is instant; press scales to 0.96.
 */
export function iconButtonClass({ variant = 'ghost', size = 'md', extendHitArea = true, menu = false }: IconButtonOptions = {}) {
	return cn(
		'grid shrink-0 cursor-pointer place-items-center rounded-md disabled:cursor-not-allowed disabled:opacity-40',
		ICON_BUTTON_VARIANT[variant],
		ICON_BUTTON_SIZE[size],
		pressClass,
		focusRingClass,
		extendHitArea && hitAreaClass,
		menu && 'data-popup-open:bg-overlay-hover',
	);
}

type TooltipIconButtonProps = Omit<React.ComponentProps<'button'>, 'aria-label'> &
	Omit<IconButtonOptions, 'menu'> & {
		label: string;
		side?: 'top' | 'right' | 'bottom' | 'left';
	};

/**
 * Icon-only button with a matching tooltip and accessible name. Hover state is
 * instant; press scales to 0.96.
 */
export function TooltipIconButton({
	label,
	side = 'top',
	variant,
	size,
	extendHitArea,
	className,
	children,
	...props
}: TooltipIconButtonProps) {
	return (
		<Tooltip>
			<TooltipTrigger
				render={
					<button
						type="button"
						aria-label={label}
						className={cn(iconButtonClass({ variant, size, extendHitArea }), className)}
						{...props}
					>
						{children}
					</button>
				}
			/>
			<TooltipContent side={side}>{label}</TooltipContent>
		</Tooltip>
	);
}

/** CSS colour for each non-neutral tone, for tints mixed at runtime. */
export const TONE_COLOR = {
	primary: 'var(--primary)',
	warning: 'var(--warning)',
	violet: 'var(--chart-3)',
	amber: 'var(--chart-4)',
	success: 'var(--success)',
	danger: 'var(--destructive)',
	info: 'var(--info)',
} as const;

export type Tone = keyof typeof TONE_COLOR | 'neutral';

type ToneBadgeProps = {
	tone: Tone;
	children: React.ReactNode;
	onClick?: () => void;
	className?: string;
};

/**
 * Tone fills mixed from `--tone`. On a white page the fill carries the colour and the
 * border only defines the edge; dark keeps a fainter fill under a stronger border.
 * The light edge is translucent so it sits on any row tint, and where relative colours
 * work its chroma is capped first: a translucent edge of a tone outside sRGB (the info
 * blue) otherwise renders yellow at the rounded corners.
 */
const toneBadgeClass = cn(
	'[--tone-edge:color-mix(in_oklab,var(--tone)_25%,transparent)]',
	'supports-[color:oklch(from_red_l_c_h)]:[--tone-edge:color-mix(in_oklab,oklch(from_var(--tone)_l_min(c,0.12)_h)_25%,transparent)]',
	'border-(--tone-edge) bg-[color-mix(in_oklab,var(--tone)_14%,transparent)]',
	'text-[color-mix(in_oklab,var(--tone),var(--foreground)_32%)]',
	'dark:border-[color-mix(in_oklab,var(--tone)_35%,transparent)] dark:bg-[color-mix(in_oklab,var(--tone)_9%,transparent)]',
);

/** Small tinted label. Clickable when `onClick` is set. */
export function ToneBadge({ tone, children, onClick, className }: ToneBadgeProps) {
	const color = tone === 'neutral' ? null : TONE_COLOR[tone];
	const props = {
		className: cn(
			'inline-flex h-5 shrink-0 items-center gap-1 whitespace-nowrap rounded-[5px] border px-1.5 text-xs [&_svg]:size-3',
			color ? toneBadgeClass : 'border-border bg-muted/60 text-muted-foreground',
			onClick && cn('cursor-pointer', pressClass, focusRingClass),
			className,
		),
		style: color ? ({ '--tone': color } as React.CSSProperties) : undefined,
	};
	return onClick ? (
		<button type="button" onClick={onClick} {...props}>
			{children}
		</button>
	) : (
		<span {...props}>{children}</span>
	);
}

type SearchFieldProps = Omit<React.ComponentProps<'input'>, 'type'> & {
