}

/**
 * Sideways-scrolling row whose children keep their shadows. A scroll container
 * clips everything outside its padding box, which would shave the ring and
 * drop shadow off raised children; the matching negative margin and padding
 * give them room without moving the row.
 */
export const scrollRowClass = '-m-2 overflow-x-auto p-2 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden';

type FilterGroupProps<T extends string> = {
	label: string;
	value: T;
	options: { value: T; label: string; count?: number; icon?: LucideIcon }[];
	onChange: (value: T) => void;
	/** Shows only icons in narrow containers; labels stay available to screen readers. */
	compact?: boolean;
	/** Styles the pill row, e.g. a tinted track. */
	className?: string;
	/** Styles the scroll wrapper, e.g. to stop it shrinking in a toolbar. */
	rootClassName?: string;
	/** Locale for the counts. Defaults to en-US. */
	locale?: string;
};

/** Single-choice filter pills with optional counts; scrolls sideways when narrow. */
export function FilterGroup<T extends string>({ label, value, options, onChange, compact = false, className, rootClassName, locale }: FilterGroupProps<T>) {
	const rtl = useDirection() === 'rtl';
	const { ref, style } = useScrollFade<HTMLDivElement>();
	return (
		<div ref={ref} style={style} className={cn(scrollRowClass, 'min-w-0', rootClassName)}>
			<div role="radiogroup" aria-label={label} className={cn('flex w-max gap-1', className)}>
				{options.map((option, index) => {
					const active = value === option.value;
					return (
						<button
							key={option.value}
							type="button"
							role="radio"
							aria-checked={active}
							tabIndex={active ? 0 : -1}
							onKeyDown={(event) => {
								const nextIndex = event.key === 'Home' ? 0
									: event.key === 'End' ? options.length - 1
									: event.key === (rtl ? 'ArrowLeft' : 'ArrowRight') || event.key === 'ArrowDown' ? (index + 1) % options.length
									: event.key === (rtl ? 'ArrowRight' : 'ArrowLeft') || event.key === 'ArrowUp' ? (index - 1 + options.length) % options.length
									: undefined;
								if (nextIndex === undefined) return;
								event.preventDefault();
								event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>('[role="radio"]')[nextIndex]?.focus();
								onChange(options[nextIndex]!.value);
							}}
							onClick={() => onChange(option.value)}
							className={cn(
								'inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-md px-2 text-[0.8125rem] pointer-coarse:h-9',
								pressClass,
								focusRingClass,
								active ? 'bg-card font-medium text-foreground shadow-card' : 'text-muted-foreground hover:text-foreground',
							)}
						>
							{option.icon ? <option.icon aria-hidden="true" className="size-3.5 shrink-0" /> : null}
							<span className={compact && option.icon ? 'sr-only @md/view:not-sr-only' : undefined}>{option.label}</span>
							{option.count === undefined ? null : (
								<span className={cn('text-xs tabular-nums', active ? 'text-muted-foreground' : 'text-subtle-foreground')}>{formatCount(option.count, locale)}</span>
							)}
						</button>
					);
				})}
			</div>
		</div>
	);
}

type SegmentedChoice<T extends string> = { value: T; label: string; icon?: LucideIcon };

type SegmentedProps<T extends string> = {
	label: string;
	value: T;
	options: SegmentedChoice<T>[];
	onChange: (value: T) => void;
	className?: string;
};

/**
 * Two-to-four option segmented control. The track has a 6px radius and 2px
 * padding, so each segment is 4px (concentric with the track).
 */
export function Segmented<T extends string>({ label, value, options, onChange, className }: SegmentedProps<T>) {
	return (
		<div role="radiogroup" aria-label={label} className={cn('flex gap-0.5 rounded-sm bg-muted p-0.5', className)}>
			{options.map((option) => {
				const Icon = option.icon;
				const active = value === option.value;
				return (
					<button
						key={option.value}
						type="button"
						role="radio"
						aria-checked={active}
						aria-label={Icon ? option.label : undefined}
						onClick={() => onChange(option.value)}
						className={cn(
							'grid h-7 flex-1 cursor-pointer place-items-center whitespace-nowrap rounded-[4px] px-2 text-[0.8125rem]',
							pressClass,
							focusRingClass,
							active ? 'bg-card font-medium text-foreground shadow-card' : 'text-muted-foreground hover:text-foreground',
						)}
					>
						{Icon ? <Icon aria-hidden="true" className="size-3.5" /> : option.label}
					</button>
				);
			})}
		</div>
	);
}

/**
 * Card surfaces whose full-bleed children (tinted strips, sticky columns,
 * table heads, canvas grids) must not cover the edge. `shadow-card` draws its
 * edge as an inset shadow in both modes, which keeps it safe from any clipping
 * ancestor but paints it beneath children, so the surface gets a 1px inset and
 * every child lives in `SurfaceBody`.
 */
export const surfaceInsetClass = 'overflow-hidden p-px';

export function SurfaceBody({ className, children, ...props }: React.ComponentProps<'div'>) {
	return (
		<div className={cn('relative h-full overflow-hidden rounded-[inherit]', className)} {...props}>
			{children}
		</div>
	);
}

/** Staggered entrance for a column of blocks: each child waits `step` ms longer. */
export function staggerStyle(index: number, step = 80): React.CSSProperties {
	return { animationDelay: `${index * step}ms` };
}

export const enterClass = 'animate-[ai-fade-up_var(--duration-slow)_var(--ease-out)_both] motion-reduce:animate-none';

/**
 * Ref that toggles the DOM `inert` property. React 18 has no `inert` prop and
 * React 19 treats it as boolean, so setting the property works on both.
 */
export function useInert<T extends HTMLElement>(inert: boolean) {
	return React.useCallback(
		(node: T | null) => {
			if (node) node.inert = inert;
		},
		[inert],
	);
}

'use client';

import * as React from 'react';

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

export function prefersReducedMotion() {
	return typeof window !== 'undefined' && Boolean(window.matchMedia?.(REDUCED_MOTION_QUERY).matches);
}

function subscribeReducedMotion(onChange: () => void) {
	const query = typeof window === 'undefined' ? undefined : window.matchMedia?.(REDUCED_MOTION_QUERY);
	query?.addEventListener('change', onChange);
	return () => query?.removeEventListener('change', onChange);
}

/** Reduced-motion preference that renders `false` on the server and hydrates without a mismatch. */
export function useReducedMotion() {
	return React.useSyncExternalStore(subscribeReducedMotion, prefersReducedMotion, () => false);
}

'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';
import { Sheet, SheetContent, SheetTitle } from '@/components/ui/sheet';
import { TooltipProvider } from '@/components/ui/tooltip';

/** An icon for a navigation row or account action: any component that takes a class name. */
type WorkspaceIcon = React.ComponentType<{ className?: string; 'aria-hidden'?: boolean | 'true' | 'false' }>;

/** The product mark at the top of the sidebar. */
type WorkspaceBrand = {
	name: React.ReactNode;
	description?: React.ReactNode;
	href?: string;
	logo?: React.ReactNode;
};

/** One sidebar destination. Rows are links, so hosts keep their own router. */
type WorkspaceNavigationItem = {
	id: string;
	label: React.ReactNode;
	href: string;
	isActive?: boolean;
	disabled?: boolean;
	icon?: WorkspaceIcon;
	/** Quiet trailing value, such as a count. */
	badge?: React.ReactNode;
};

/** A titled run of sidebar rows. */
type WorkspaceNavigationGroup = {
	id: string;
	label?: React.ReactNode;
	items: readonly WorkspaceNavigationItem[];
};

type WorkspaceAccountActionBase = {
	id: string;
	label: React.ReactNode;
	icon?: WorkspaceIcon;
	disabled?: boolean;
	variant?: 'default' | 'destructive';
};

/** A session action in the account menu: a link, or a callback. */
type WorkspaceAccountAction = WorkspaceAccountActionBase &
	({ href: string; onSelect?: never } | { href?: never; onSelect: () => void });

type WorkspaceAccountActionGroup = {
	id: string;
	label?: React.ReactNode;
	actions: readonly WorkspaceAccountAction[];
};

/** The signed-in person shown at the foot of the sidebar. */
type WorkspaceAccount = {
	name: string;
	secondaryLabel?: string;
	avatarUrl?: string;
	avatarAlt?: string;
	/** Initials when there is no avatar; derived from `name` by default. */
	fallback?: string;
	actionGroups?: readonly WorkspaceAccountActionGroup[];
};

type WorkspaceShellContextValue = {
	/** Opens the navigation drawer shown below the sidebar breakpoint. */
	openNav: () => void;
};

const WorkspaceShellContext = React.createContext<WorkspaceShellContextValue>({ openNav: () => {} });

/** The enclosing workspace shell. Outside one, `openNav` is a no-op. */
function useWorkspaceShell() {
	return React.useContext(WorkspaceShellContext);
}

type WorkspaceSidebarRenderProps = {
	/** `rail` sits beside the content from the `3xl` container width up; `drawer` renders inside the mobile sheet. */
	mode: 'rail' | 'drawer';
	/** Icon-rail state. Always false in the drawer. */
	collapsed: boolean;
	onCollapsedChange: (collapsed: boolean) => void;
	/** Closes the drawer. Call it after any navigation item is chosen. */
	onNavigate: () => void;
};

type WorkspaceShellProps = {
	/** Rendered twice: once as the rail and once inside the navigation drawer. */
	sidebar: (props: WorkspaceSidebarRenderProps) => React.ReactNode;
	children: React.ReactNode;
	/** `data-slot` on the root, so hosts and tests can target a specific template. */
	slot?: string;
	defaultSidebarCollapsed?: boolean;
	/**
	 * Sits the workspace in a rounded, hairline-edged frame on a canvas one tier
	 * darker than the content, for hosts that present it as an app window rather
	 * than the whole page. `className` then lands on the canvas.
	 */
	framed?: boolean;
	className?: string;
};

/**
 * Workspace layout shared by the application templates: a collapsible sidebar
 * rail beside the main region, a left drawer below the `3xl` container width,
 * a skip link, and one tooltip provider. The root is the `ws` container, so
 * every view sizes itself to the space it is given rather than the viewport.
 */
function WorkspaceShell({
	sidebar,
	children,
	slot = 'workspace-shell',
	defaultSidebarCollapsed = false,
	framed = false,
	className,
}: WorkspaceShellProps) {
	const [collapsed, setCollapsed] = React.useState(defaultSidebarCollapsed);
	const [navOpen, setNavOpen] = React.useState(false);
	const mainId = React.useId();
	const context = React.useMemo<WorkspaceShellContextValue>(() => ({ openNav: () => setNavOpen(true) }), []);
	const closeNav = React.useCallback(() => setNavOpen(false), []);

	const shell = (
		<div
			data-slot={slot}
			data-framed={framed || undefined}
			className={cn(
				'@container/ws relative flex h-full min-h-0 w-full overflow-hidden bg-background text-foreground',
				framed ? 'min-w-0 flex-1 rounded-xl border border-border shadow-xs' : className,
			)}
		>
			<a
				href={`#${mainId}`}
				className="sr-only z-50 rounded-md bg-card px-3 py-2 text-sm shadow-card focus:not-sr-only focus:absolute focus:top-2 focus:start-2"
			>
				Skip to main content
			</a>
			<div className="hidden h-full @3xl/ws:flex">
				{sidebar({ mode: 'rail', collapsed, onCollapsedChange: setCollapsed, onNavigate: () => {} })}
			</div>
			<main id={mainId} tabIndex={-1} className="@container/view flex min-w-0 flex-1 outline-none">
				{children}
			</main>
		</div>
	);

	return (
		<WorkspaceShellContext.Provider value={context}>
			<TooltipProvider>
				{framed ? (
					<div
						data-slot="workspace-canvas"
						// One tier past the sidebar so the frame edge reads against it: the page mixed toward the text colour
						// in light (about #f1f1f1 on the builtin theme, and preset-aware), and toward black in dark.
						className={cn(
							'flex h-full min-h-0 w-full bg-[color-mix(in_oklab,var(--background),var(--foreground)_6%)] p-2 sm:p-3',
							'dark:bg-[color-mix(in_oklab,var(--background),black_35%)]',
							className,
						)}
					>
						{shell}
					</div>
				) : (
					shell
				)}
				<Sheet open={navOpen} onOpenChange={setNavOpen}>
					<SheetContent side="left" showClose={false} className="w-72 max-w-[85vw] gap-0 p-0 sm:max-w-72">
						<SheetTitle className="sr-only">Navigation</SheetTitle>
						{sidebar({ mode: 'drawer', collapsed: false, onCollapsedChange: setCollapsed, onNavigate: closeNav })}
					</SheetContent>
				</Sheet>
			</TooltipProvider>
		</WorkspaceShellContext.Provider>
	);
}

export { useWorkspaceShell, WorkspaceShell, WorkspaceShellContext };
export type {
	WorkspaceAccount,
	WorkspaceAccountAction,
	WorkspaceAccountActionGroup,
	WorkspaceBrand,
	WorkspaceIcon,
	WorkspaceNavigationGroup,
	WorkspaceNavigationItem,
	WorkspaceShellContextValue,
	WorkspaceShellProps,
	WorkspaceSidebarRenderProps,
};

'use client';

import type { LucideIcon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { focusRingClass, SurfaceBody, surfaceInsetClass, TONE_COLOR, ToneBadge, type Tone } from '@/components/ui/workspace-kit/primitives';
import { useScrollFade } from '@/lib/use-scroll-fade';

/** A status as the UI shows it: a short label and the tone that colours it. */
export type Presentation = { label: string; tone: Tone; description?: string };

/** Hairline dashed rule used between sections of one surface. */
export const dashedRule = 'border-dashed border-foreground/10';

/** Header row and body row classes shared by every workspace table. */
// `th` centres itself unless its row sets an explicit alignment, and `start` is not explicit, so the head names both directions.
export const tableHeadClass = 'bg-muted/60 text-left rtl:text-right text-xs font-normal text-muted-foreground [&_th]:px-4 [&_th]:py-2 [&_th]:font-normal';
export const tableRowClass = 'border-t border-border align-middle [&_td]:px-4 [&_td]:py-2.5';
/**
 * Heading row that opens a group of body rows, tinted like the header so the
 * break reads without a heavier line. Pair it with `<th scope="rowgroup" colSpan>`.
 */
export const tableGroupRowClass =
	'border-t border-border bg-muted/60 [&_th]:px-4 [&_th]:py-1.5 [&_th]:text-start [&_th]:text-xs [&_th]:font-medium [&_th]:text-muted-foreground';

/** A native select styled like the kit's inputs. */
export const nativeSelectClass = cn('h-8 rounded-md border border-border bg-card px-2 text-[0.8125rem] text-foreground shadow-2xs', focusRingClass);

/**
 * Card around a table that scrolls sideways below `minWidth`, keeping the card
 * edge visible over full-bleed header rows. An edge fades while there is more
 * to scroll to, so a table cut off on a phone reads as scrollable.
 */
export function TableSurface({ children, className, minWidth = '40rem' }: { children: React.ReactNode; className?: string; minWidth?: string }) {
	const { ref, style } = useScrollFade<HTMLDivElement>();
	return (
		<div className={cn(surfaceInsetClass, 'rounded-xl bg-card shadow-card', className)}>
			<SurfaceBody>
				<div ref={ref} className="relative overflow-x-auto" style={style}>
					<table className="w-full border-collapse text-[0.8125rem]" style={{ minWidth }}>
						{children}
					</table>
				</div>
			</SurfaceBody>
		</div>
	);
}

/** Small tinted status label from a presentation map entry. */
export function StatusBadge({ presentation, className, children }: { presentation: Presentation; className?: string; children?: React.ReactNode }) {
	return (
		<ToneBadge tone={presentation.tone} className={className}>
			{children}
			{presentation.label}
		</ToneBadge>
